"""New agent cards AG-100…AG-122 (V12 Group F). Token economics use the Part 7.3 §7.3.2
list prices (verify at time of implementation, as of 27 Nov 2026) and ₹90/US$ [ASSUMPTION-861]."""
FX = 90
PRICE = {"1a": dict(i=0.10, o=0.50, cr=0.01, cw=0.125), "1b": dict(i=2.00, o=10.0, cr=0.10, cw=2.50)}
HIT = 0.60

def per_call(tier, tin, cache, tout):
    p = PRICE[tier]
    return FX * ((tin - cache) * p["i"] + cache * (HIT * p["cr"] + (1 - HIT) * p["cw"]) + tout * p["o"]) / 1e6

def econ(primary, tin, cache, tout, calls, esc):
    h = per_call("1a", tin, cache, tout); s = per_call("1b", tin, cache, tout)
    if primary == "1a":
        blend = (1 - esc) * h + esc * s
        f = (f"Haiku per call = 90 × [{tin-cache:,}×0.10 + {cache:,}×(0.6×0.01 + 0.4×0.125) + {tout:,}×0.50] ÷ 10⁶ = **₹{h:.3f}**; "
             f"Sonnet per call = 90 × [{tin-cache:,}×2 + {cache:,}×(0.6×0.10 + 0.4×2.50) + {tout:,}×10] ÷ 10⁶ = **₹{s:.3f}**; blended at e = {int(esc*100)}% = **₹{blend:.3f}**")
    else:
        blend = s
        f = f"Sonnet per call = 90 × [{tin-cache:,}×2 + {cache:,}×(0.6×0.10 + 0.4×2.50) + {tout:,}×10] ÷ 10⁶ = **₹{s:.3f}**"
    base = blend * calls
    return blend, base, f

